import React, { useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Sparkles, Crown, ArrowRight } from "lucide-react";
import { BRAND } from "../types";

// ══════════════════════════════════════════════════════════════
// Your wedding scene image
// ══════════════════════════════════════════════════════════════
const BACKGROUND_IMAGE =
  "/images/pita_Wide-angle_3D_rendered_luxury_wedding_venue_showcase_birds_eye_f75ac395-fb47-45cb-9862-8b54a5c34201.jpg";

// How close the camera zooms in
const ZOOM = 1.5;

// Zoom transition duration (seconds)
const ZOOM_DURATION = 0.9;

// ══════════════════════════════════════════════════════════════
// Products — positions tuned to the wedding venue photograph
// ══════════════════════════════════════════════════════════════
const products = [
  {
    id: 1,
    name: "Ceiling Drapes",
    subtitle: "Flowing gold & ivory overhead drapes",
    position: { top: "10%", left: "30%" },
    focusPoint: { x: 30, y: 8 },
  },
  {
    id: 2,
    name: "Chandeliers",
    subtitle: "Crystal chandeliers with warm glow",
    position: { top: "24%", left: "58%" },
    focusPoint: { x: 58, y: 24 },
  },
  {
    id: 3,
    name: "Chair Covers",
    subtitle: "White covers with gold sash bows",
    position: { top: "76%", left: "20%" },
    focusPoint: { x: 20, y: 76 },
  },
  {
    id: 4,
    name: "Table Covers",
    subtitle: "Gold-clothed round tables",
    position: { top: "60%", left: "40%" },
    focusPoint: { x: 40, y: 60 },
  },
  {
    id: 5,
    name: "Artificial Flowers",
    subtitle: "Luxurious floral arrangements",
    position: { top: "54%", left: "10%" },
    focusPoint: { x: 10, y: 54 },
  },
  {
    id: 6,
    name: "Decor Accessories",
    subtitle: "Candelabras, vases & gold accents",
    position: { top: "46%", left: "32%" },
    focusPoint: { x: 32, y: 46 },
  },
  {
    id: 7,
    name: "Curtains",
    subtitle: "Sheer floor-to-ceiling installations",
    position: { top: "36%", left: "88%" },
    focusPoint: { x: 88, y: 36 },
  },
  {
    id: 8,
    name: "Premium Fabrics",
    subtitle: "Luxurious flowing silk textures",
    position: { top: "12%", left: "74%" },
    focusPoint: { x: 74, y: 12 },
  },
];

// ══════════════════════════════════════════════════════════════
// Component
// ══════════════════════════════════════════════════════════════
export default function Hero3D({ onOpenQuote }: { onOpenQuote: () => void }) {
  const [activeId, setActiveId] = useState<number | null>(null);
  const [imgLoaded, setImgLoaded] = useState(false);

  const scrollToCollections = () =>
    document.getElementById("collections")?.scrollIntoView({ behavior: "smooth" });

  const activeProduct = activeId !== null ? products.find((p) => p.id === activeId) : null;
  const isZoomed = activeId !== null;

  const handleEnter = useCallback((id: number) => setActiveId(id), []);
  const handleLeave = useCallback(() => setActiveId(null), []);

  // Background element is 250% x 250% so zoom never shows empty space.
  // Visible viewport shows the center 40% of this element.
  // When we scale(1.5) from the focus point, we still stay within bounds.
  const BG_SIZE = 250; // percentage

  // The visible window maps to [30%, 70%] of the BG element in each axis.
  // When zoomed, transform-origin at (fx, fy) keeps that point fixed
  // and scales everything else around it.
  const bgOriginX = activeProduct ? activeProduct.focusPoint.x : 50;
  const bgOriginY = activeProduct ? activeProduct.focusPoint.y : 50;

  // Label placement: flip to left side if product is on the right half
  const labelSide = (fp: { x: number }) => (fp.x > 60 ? "right" : "left");

  return (
    <section id="top" className="relative min-h-screen overflow-hidden select-none">
      {/* ── Loading skeleton ── */}
      {!imgLoaded && (
        <div className="absolute inset-0 bg-gradient-to-br from-amber-900 via-amber-800 to-gray-900 flex items-center justify-center z-50">
          <div className="text-center">
            <div className="w-14 h-14 border-4 border-amber-400 border-t-transparent rounded-full animate-spin mx-auto mb-3" />
            <p className="text-amber-400/80 text-sm tracking-wide">Loading experience…</p>
          </div>
        </div>
      )}

      {/* ── Background image — oversized so zoom never clips ── */}
      <div
        className="absolute pointer-events-none"
        style={{
          top: `${-(BG_SIZE - 100) / 2}%`,
          left: `${-(BG_SIZE - 100) / 2}%`,
          width: `${BG_SIZE}%`,
          height: `${BG_SIZE}%`,
          backgroundImage: `url('${BACKGROUND_IMAGE}')`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          transform: isZoomed ? `scale(${ZOOM})` : "scale(1)",
          transformOrigin: `${bgOriginX}% ${bgOriginY}%`,
          transition: `transform ${ZOOM_DURATION}s cubic-bezier(0.25, 0.46, 0.45, 0.94)`,
          willChange: "transform",
        }}
      />
      {/* Hidden img to detect load */}
      <img
        src={BACKGROUND_IMAGE}
        alt=""
        className="hidden"
        onLoad={() => setImgLoaded(true)}
      />

      {/* ── Dark overlay — fades during zoom so image shows through ── */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "linear-gradient(to bottom, rgba(0,0,0,0.65) 0%, rgba(0,0,0,0.25) 45%, rgba(0,0,0,0.7) 100%)",
          opacity: isZoomed ? 0.15 : 1,
          transition: "opacity 0.7s ease",
        }}
      />

      {/* ── Vignette ── */}
      <div
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,0.65) 100%)",
          opacity: isZoomed ? 0.85 : 0.45,
          transition: "opacity 0.7s ease",
        }}
      />

      {/* ── Radial warm glow at zoom focus ── */}
      <div
        className="absolute inset-0 pointer-events-none z-10"
        style={{
          background:
            isZoomed && activeProduct
              ? `radial-gradient(ellipse 40% 40% at ${activeProduct.focusPoint.x}% ${activeProduct.focusPoint.y}%, rgba(212,175,55,0.18), transparent 70%)`
              : "none",
          transition: "opacity 0.6s ease",
          opacity: isZoomed ? 1 : 0,
        }}
      />

      {/* ── Hotspot layer ── */}
      <div className="absolute inset-0 z-20">
        {products.map((product) => {
          const isActive = activeId === product.id;
          const side = labelSide(product.focusPoint);

          return (
            <motion.div
              key={product.id}
              className="absolute"
              style={{
                top: product.position.top,
                left: product.position.left,
                transform: "translate(-50%, -50%)",
              }}
              onMouseEnter={() => handleEnter(product.id)}
              onMouseLeave={handleLeave}
              initial={{ scale: 0, opacity: 0 }}
              animate={{
                scale: 1,
                opacity: isZoomed && !isActive ? 0.12 : 1,
              }}
              transition={{
                delay: 0.5 + product.id * 0.09,
                type: "spring",
                stiffness: 240,
                damping: 22,
              }}
            >
              {/* ── Pulsing dot ── */}
              <motion.div
                className="relative w-10 h-10 md:w-12 md:h-12 cursor-pointer"
                whileHover={{ scale: 1.4 }}
              >
                {/* Outer ring */}
                <motion.div
                  className="absolute inset-0 border-2 border-amber-400/70 rounded-full"
                  animate={
                    isActive
                      ? { scale: [1, 2.5, 1], opacity: [1, 0, 1] }
                      : { scale: [1, 1.8, 1], opacity: [0.4, 0, 0.4] }
                  }
                  transition={{ duration: 2.2, repeat: Infinity, ease: "easeInOut" }}
                />
                {/* Second ring (staggered) */}
                <motion.div
                  className="absolute inset-0 border border-amber-300/40 rounded-full"
                  animate={
                    isActive
                      ? { scale: [1, 2, 1], opacity: [0.8, 0, 0.8] }
                      : { scale: [1, 1.5, 1], opacity: [0.2, 0, 0.2] }
                  }
                  transition={{
                    duration: 2.2,
                    repeat: Infinity,
                    ease: "easeInOut",
                    delay: 0.4,
                  }}
                />
                {/* Inner dot */}
                <motion.div
                  className="absolute inset-1.5 rounded-full flex items-center justify-center"
                  style={{
                    background: "linear-gradient(135deg, #d4af37, #b8941f)",
                    boxShadow: isActive
                      ? "0 0 35px rgba(212,175,55,0.8), 0 0 60px rgba(212,175,55,0.3)"
                      : "0 0 18px rgba(212,175,55,0.4)",
                  }}
                  animate={{ scale: isActive ? [1, 1.25, 1] : [1, 1.08, 1] }}
                  transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}
                >
                  <div className="w-2 h-2 bg-white rounded-full shadow-sm" />
                </motion.div>
              </motion.div>

              {/* ── Label card ── */}
              <AnimatePresence>
                {isActive && (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.88, y: 8 }}
                    animate={{ opacity: 1, scale: 1, y: 0 }}
                    exit={{ opacity: 0, scale: 0.88, y: 8 }}
                    transition={{ duration: 0.35, ease: [0.25, 0.46, 0.45, 0.94] }}
                    className={`absolute top-1/2 -translate-y-1/2 whitespace-nowrap z-50 ${
                      side === "right"
                        ? "right-full mr-5"
                        : "left-full ml-5"
                    }`}
                  >
                    {/* Connector line */}
                    <div
                      className={`absolute top-1/2 -translate-y-1/2 w-6 h-[2px] bg-gradient-to-r ${
                        side === "right"
                          ? "left-full ml-0 from-amber-400 to-transparent"
                          : "right-full mr-0 from-transparent to-amber-400"
                      }`}
                    />

                    <div className="relative bg-gradient-to-br from-white/95 via-amber-50/90 to-white/95 backdrop-blur-xl rounded-2xl px-6 py-4 shadow-2xl shadow-black/40 border border-amber-300/30">
                      {/* Gold accent bar */}
                      <div
                        className={`absolute top-3 bottom-3 w-1 rounded-full bg-gradient-to-b from-amber-400 via-amber-500 to-amber-400 ${
                          side === "right" ? "-right-1" : "-left-1"
                        }`}
                      />

                      <h3 className="text-amber-800 font-bold text-base md:text-lg mb-0.5 leading-tight">
                        {product.name}
                      </h3>
                      <p className="text-gray-500 text-xs md:text-sm mb-2.5 leading-snug">
                        {product.subtitle}
                      </p>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          scrollToCollections();
                        }}
                        className="text-xs text-amber-600 hover:text-amber-900 flex items-center gap-1.5 font-semibold transition-all duration-300 hover:gap-3"
                      >
                        View Collection
                        <ArrowRight size={12} className="transition-transform group-hover:translate-x-1" />
                      </button>
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>

      {/* ── Floating golden particles ── */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none z-10">
        {[...Array(22)].map((_, i) => {
          const size = 1 + (i % 3) * 0.5;
          return (
            <motion.div
              key={i}
              className="absolute rounded-full"
              style={{
                width: size,
                height: size,
                left: `${4 + ((i * 4.7) % 92)}%`,
                top: `${6 + ((i * 6.3) % 88)}%`,
                background: `rgba(212, 175, 55, ${0.3 + (i % 4) * 0.12})`,
              }}
              animate={{
                y: [0, -(50 + (i % 5) * 20), 0],
                x: [0, Math.sin(i * 0.7) * 18, 0],
                opacity: [0, 0.6 + (i % 3) * 0.15, 0],
                scale: [0, 1, 0],
              }}
              transition={{
                duration: 3.5 + (i % 5) * 0.8,
                repeat: Infinity,
                delay: i * 0.28,
                ease: "easeInOut",
              }}
            />
          );
        })}
      </div>

      {/* ── Content overlay (fades out during zoom) ── */}
      <AnimatePresence>
        {!isZoomed && (
          <motion.div
            key="hero-content"
            className="relative z-30 container mx-auto px-6 text-center pointer-events-none"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0, filter: "blur(8px)" }}
            transition={{ duration: 0.6 }}
          >
            <div className="max-w-5xl mx-auto">
              {/* Title */}
              <motion.h1
                initial={{ opacity: 0, y: 50 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.6, duration: 0.8 }}
                className="text-5xl sm:text-6xl md:text-7xl lg:text-[90px] font-bold text-white mb-4 tracking-tight"
                style={{ fontFamily: "Georgia, serif" }}
              >
                {["D", "SAJAWAT"].map((word, wi) => (
                  <span key={wi} className="inline-block mr-3 md:mr-6">
                    {word.split("").map((letter, li) => (
                      <motion.span
                        key={`${wi}-${li}`}
                        className="inline-block"
                        initial={{ opacity: 0, y: 80, rotateX: -90 }}
                        animate={{ opacity: 1, y: 0, rotateX: 0 }}
                        transition={{
                          duration: 0.7,
                          delay: 0.7 + wi * 0.4 + li * 0.06,
                          ease: [0.34, 1.56, 0.64, 1],
                        }}
                      >
                        <span className="bg-gradient-to-b from-amber-200 via-amber-400 to-amber-300 bg-clip-text text-transparent drop-shadow-lg">
                          {letter}
                        </span>
                      </motion.span>
                    ))}
                  </span>
                ))}
              </motion.h1>

              {/* Tagline */}
              <motion.div
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: 1.1, duration: 0.6 }}
                className="flex items-center justify-center gap-3 md:gap-5 mb-6"
              >
                <motion.div
                  animate={{ rotate: [0, 12, -12, 0], scale: [1, 1.1, 1] }}
                  transition={{ duration: 3.5, repeat: Infinity, ease: "easeInOut" }}
                >
                  <Crown className="text-amber-400 drop-shadow-lg" size={28} />
                </motion.div>
                <p
                  className="text-xl md:text-3xl lg:text-4xl text-amber-300 italic drop-shadow-md"
                  style={{ fontFamily: "Georgia, serif" }}
                >
                  {BRAND.tagline}
                </p>
                <motion.div
                  animate={{ rotate: [0, -12, 12, 0], scale: [1, 1.1, 1] }}
                  transition={{ duration: 3.5, repeat: Infinity, ease: "easeInOut", delay: 0.5 }}
                >
                  <Crown className="text-amber-400 drop-shadow-lg" size={28} />
                </motion.div>
              </motion.div>

              {/* Subtitle */}
              <motion.p
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1.3 }}
                className="text-base md:text-lg lg:text-xl text-white/75 max-w-2xl mx-auto mb-10 leading-relaxed drop-shadow-sm"
              >
                Hover over the glowing dots to explore our complete wedding decor collection.
              </motion.p>

              {/* CTAs */}
              <motion.div
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 1.5 }}
                className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center items-center pointer-events-auto"
              >
                <motion.button
                  onClick={scrollToCollections}
                  className="px-8 md:px-12 py-4 md:py-5 bg-gradient-to-r from-amber-400 via-amber-500 to-amber-400 bg-[length:200%_100%] text-white font-bold rounded-full flex items-center justify-center gap-3 text-base md:text-lg shadow-2xl shadow-amber-500/40 relative overflow-hidden"
                  whileHover={{ scale: 1.05, boxShadow: "0 25px 80px rgba(212,175,55,0.5)" }}
                  whileTap={{ scale: 0.98 }}
                >
                  <motion.div
                    className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -skew-x-12"
                    initial={{ x: "-100%" }}
                    whileHover={{ x: "200%" }}
                    transition={{ duration: 0.7 }}
                  />
                  <Sparkles size={20} className="relative z-10" />
                  <span className="relative z-10">Explore Collections</span>
                </motion.button>

                <motion.button
                  onClick={onOpenQuote}
                  className="px-8 md:px-12 py-4 md:py-5 bg-white/10 backdrop-blur-xl border-2 border-white/30 text-white font-bold rounded-full flex items-center justify-center gap-3 text-base md:text-lg hover:bg-white hover:text-gray-900 transition-all duration-300"
                  whileHover={{ scale: 1.05, borderColor: "rgba(212,175,55,0.8)", boxShadow: "0 20px 60px rgba(212,175,55,0.2)" }}
                  whileTap={{ scale: 0.98 }}
                >
                  Get a Quote
                  <motion.span animate={{ x: [0, 6, 0] }} transition={{ duration: 1.5, repeat: Infinity }} className="text-xl">
                    →
                  </motion.span>
                </motion.button>
              </motion.div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Instruction tooltip ── */}
      <AnimatePresence>
        {!isZoomed && (
          <motion.div
            key="tooltip"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 10 }}
            transition={{ delay: 2.5, duration: 0.6 }}
            className="absolute bottom-28 left-1/2 -translate-x-1/2 z-30"
          >
            <motion.div
              className="bg-white/10 backdrop-blur-md rounded-full px-5 py-2.5 border border-white/15"
              animate={{ y: [0, 6, 0] }}
              transition={{ duration: 2.8, repeat: Infinity, ease: "easeInOut" }}
            >
              <p className="text-white/85 text-sm flex items-center gap-2">
                <motion.span
                  className="w-2.5 h-2.5 bg-amber-400 rounded-full inline-block"
                  animate={{ scale: [1, 1.5, 1], opacity: [1, 0.5, 1] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                />
                Hover the glowing dots to explore products
              </p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Bottom gradient fade ── */}
      <div className="absolute bottom-0 left-0 right-0 h-32 md:h-40 bg-gradient-to-t from-[#fdf6eb] to-transparent pointer-events-none z-40" />
    </section>
  );
}
